/* eslint-disable prefer-destructuring */
/* eslint-disable react/jsx-props-no-spreading */
import React, {
  useState,
  useCallback,
  useMemo,
  useEffect,
  useRef,
  memo,
} from 'react';

import { useDispatch, useSelector } from 'react-redux';

import {
  useSessionVideoControlls
} from 'components/shared/Sessions/Context';

import useSessionColumns from 'components/features/sessions/hooks/useSessionColumns';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';

import { usePagination } from 'components/features/issues/components/ReactTable/usePagination';
import { addSessionId } from 'redux/actions/common';
import { DashboardTable, StylesProvider } from 'uxcam-frontend-components';
import { schematicFrameworks } from 'components/shared/Sessions/Video/utils';
import { useSessionTableHelper } from './utils';


import {
  SessionTableWrapper,
} from './styles';

const SessionTable = ({
  data,
  expanded,
  isLoading,
  setSortedBy,
  sortedBy,
  openIOSReplayModal,
}) => {
  const dispatch = useDispatch();
  const {
    urlReducer: urlQuery,
    selectedSessionReducer: selectedSession,
  } = useSelector((state) => state);
  const prevPaginationRef = useRef();

  const newPagination = useMemo(() => data?.pagination ? data?.pagination : prevPaginationRef?.current, [data?.pagination])
  
  const [cachedHeadersData, setCachedHeadersData] = useState([]);
  const {pagination, setPagination} = usePagination();
  const { sessionpage, sessionid: sessionIdURL } = urlQuery;
  const moveToRef = useRef();
  const [rowselection, setRowSelection] = useState([]);
  const { prevSessionCallbackRef, nextSessionCallbackRef } =
    useSessionVideoControlls();
  const { setSessionLockedModal } = useRestrictionContext();
  const headers = data?.header;

  const sessionPage = React.useMemo(() => Number(sessionpage), [sessionpage]);

  const {
    handleRowClick,
    handleUserClick,
    navigatePage,
    onItemSetActive,
    trackUserTimeEvent,
    pageChange,
    onItemPlay,
    onItemPause,
  } = useSessionTableHelper({ expanded });

  const sessionIndex = useMemo(
    () => data?.body?.findIndex(({ sessionid }) => sessionid === sessionIdURL),
    [data, sessionIdURL]
  );

  const handleSchematicReplay = (e, platform, sdkPluginType) => {
    if (e.button === 0 && platform === 2 && schematicFrameworks.includes(sdkPluginType?.toLowerCase())) {
      openIOSReplayModal();
    }
  }

  const handleClickLockedSession = useCallback( () => setSessionLockedModal( true ), [ setSessionLockedModal ] )

  const handleNext = useCallback(() => {
    moveToRef.current = undefined;
    trackUserTimeEvent(sessionIdURL);
    if (!data) {
      return;
    }
    if (sessionIndex === -1) {
      return;
    }
    const nextIndex = sessionIndex + 1;
    const isLast = data?.body?.length === nextIndex;
    if (isLast) {
      moveToRef.current = 'first';
      navigatePage(sessionPage + 1);
    } else {
      const nextId = data.body[nextIndex].sessionid;
      const isViewed = data.body[nextIndex].isViewed;
      onItemSetActive(nextId, true, !isViewed);
      // if (videoElemRef?.current) videoElemRef.current.play();
    }
  }, [onItemSetActive, sessionPage, sessionIndex, data]);

  useEffect(() => {
    if (moveToRef.current && data?.body?.length) {
      let displaySession;
      if (moveToRef.current === 'first') {
        displaySession = data.body[0];
      } else {
        displaySession = data.body[data.body.length - 1];
      }

      if (displaySession) {
        onItemSetActive(
          displaySession.sessionid,
          true,
          !displaySession?.isViewed
        );
      }
      moveToRef.current = undefined;
    }
  }, [data]);

  useEffect(() => {
    nextSessionCallbackRef.current = handleNext;
  }, [handleNext]);

  const handlePrev = useCallback(() => {
    moveToRef.current = undefined;
    trackUserTimeEvent(sessionIdURL);
    if (!data) {
      return;
    }
    if (sessionIndex === -1) {
      return;
    }
    const prevIndex = sessionIndex - 1;
    const prevPage = prevIndex === -1;
    if (prevPage) {
      if (sessionPage === 0) {
        return;
      }
      moveToRef.current = 'last';
      // move to prev page
      navigatePage(sessionPage - 1);
    } else {
      const prevId = data.body[prevIndex].sessionid;
      const isViewed = data.body[prevIndex].isViewed;
      onItemSetActive(prevId, true, !isViewed);
    }
  }, [onItemSetActive, sessionPage, sessionIndex, data]);

  useEffect(() => {
    prevSessionCallbackRef.current = handlePrev;
  }, [handlePrev]);

  useEffect(() => {
    setPagination({...pagination, pageIndex: parseInt(sessionpage || 1, 10)})
    // to clear out selected values on pagination update
    dispatch(addSessionId([]));
  }, [sessionpage]);

  useEffect(() => {
    if (moveToRef.current && data?.body?.length) {
      let displaySession;
      if (moveToRef.current === 'first') {
        displaySession = data.body[0];
      } else {
        displaySession = data.body[data.body.length - 1];
      }

      if (displaySession) {
        onItemSetActive(
          displaySession.sessionid,
          true,
          !displaySession?.isViewed
        );
      }
      moveToRef.current = undefined;
    }
  }, [data]);

  useEffect(() => {
    if (headers) setCachedHeadersData(headers);
  }, [headers])

  useEffect(() => {
    if(newPagination){
      prevPaginationRef.current = newPagination;
    }
  }, [newPagination]);

  const highlightActiveRow = useCallback(
    (row) => row.sessionid === sessionIdURL,
    [sessionIdURL]
  );

  const columns = useSessionColumns(headers || cachedHeadersData, expanded);
  const rowsData = useMemo(
    () =>
      data?.body?.map((item) => ({
        ...item,
        onItemPlay: (args) =>
          onItemPlay(
            args?.sessionId,
            args?.isActive,
            args?.isViewed,
            args?.userTime
          ),
        onItemPause: (args) => onItemPause(args?.sessionId),
        handleUserClick: (userId) => handleUserClick(userId),
        onRowClick: (row, e) => {
          const { sessionid, isViewed, sessionLocked, platform, sdkPluginType } = row;
          if (!sessionLocked) {
            handleRowClick(e, sessionid, !isViewed);
            handleSchematicReplay(e, platform, sdkPluginType);
          } else {
            handleClickLockedSession();
          }
        },
        highlightActiveRow: (row) => highlightActiveRow(row),
      })),
    [data, sessionIdURL]
  );

  useEffect(() => {
    const selectedRowId = Object.keys(rowselection).map(Number)
    const filteredBody = data?.body?.filter((el, index) => selectedRowId.includes(index))
    const selectedSessionIds = filteredBody?.map((el) => el.sessionid)
    dispatch(addSessionId(selectedSessionIds));
  }, [rowselection])

  useEffect(() => {
    const selectedRowId = Object.keys(rowselection).map(Number);
    if(selectedRowId.length > selectedSession) setRowSelection([]);
  }, [selectedSession])

  return (
    <SessionTableWrapper>
      <StylesProvider>
        <DashboardTable
          data={rowsData}
          columns={columns}
          sorting={sortedBy}
          setSorting={setSortedBy}
          resizeMode="onChange"
          isLoading={isLoading}
          expandedView={expanded}
          tableHeight={expanded ? 'calc(100vh - 164px)' : '100%'}
          pagination={{
            ...pagination,
            totalPagination: data?.pagination?.pages || 1,
          }}
          setPagination={setPagination}
          handleRouteUpdate={pageChange}
          enableSelection
          stickyHeaders={expanded ? [] : ['select', 'sessionhashofuser']}
          rowSelection={rowselection}
          setRowSelection={setRowSelection}
          emptyText={{message: 'No sessions match the current filters.'}}
      />
      </StylesProvider>
    </SessionTableWrapper>
  );
};

export default memo(SessionTable);
