const Quickbar = dynamic(import('components/common/Quickbar'));
const ColumnUpdate = dynamic(import('components/common/ColumnUpdate'));

const Toolbar = ({ expanded, session, sessionList, isFetching, onResetSuccess }) => {
  const dispatch = useDispatch();
  const { callListApi } = useAppFilter();
  const [dropdownVisible, setDropdownVisibility] = useState(false);
  const [cachedSession, setCachedSession] = useState(null);
  const [loading, setLoading] = useState(false);
  const [ sageLoading, setSageLoading ] = useState(false);
  const [ sageResMessage, setSageResMessage ] = useState(null);

  const sessionIdList = useMemo(() => sessionList?.body?.map((item) => item.sessionid) || [], [sessionList?.body]);
  const {
    urlReducer: urlQuery,
    currentAppReducer,
    appFilter,
    sessionStatisticsReducer,
  } = useSelector((state) => state);
  const { _id: appid } = currentAppReducer;
  const { sessionpage, sessionid, autoplay } = urlQuery;
  const sessionsNum = React.useMemo( () => sessionStatisticsReducer?.statsBoxes?.data?.boxes?.['Sessions']?.count?.value_this_period_number, [ sessionStatisticsReducer?.statsBoxes?.data?.boxes ] )
  const sessionSegment = appFilter?.session?.segment;
  const headers = useMemo(()=> sessionList?.header?.filter((item) => item.attribute !== 'video' && item.title !== 'Rec'), [sessionList?.header])
  const { openModal, setOpenModal, CommonModal, formRef } = useCommonModal()
  
  const { data: sessionSageData } = useQuery(
    ['sessionSage', appid],
    () => CommonApi.getSageAppRegistered(appid),
    {
      enabled: Boolean(appid && isUat),
    }
  );

  const showSessionSage = useMemo(() => isUat && sessionSageData?.data?.data?.app_exists, [ sessionSageData]);

  const handleSessionClick = (type) => {
    const segment = sessionSegment;
    const autoPlayPart = `&autoplay=${autoplay ? '1' : ' 0'}`;
    const url = urlSegmentEncoder(
      `/app/${appid}/sessions/list/${sessionpage || 1}?`,
      segment
    );
    const query = `appId=${appid}&parentType=sessionsList&sessionpage=${
      sessionpage || 1
    }&starttime=0${autoPlayPart}`;

    dispatch(trackPageViews(null, {
      eventName: type === 'back' ? 'go_back_to_session_list' : 'close_session_replay',
      track_type: 'event',
      eventProperty: {}
    }))
    Router.push(`/integration?${query}`, url);
  };

  const applyQuickFilter = async () => {
    await dispatch(applySessionCustomFilter(1));
    callListApi()
  };
  const handleVisibleChange = (flag) => setDropdownVisibility(flag);
  const setLoader = (value) => setLoading(value);

  useEffect(() => {
    if (session && session !== cachedSession) setCachedSession(session);
  }, [session]);

  const sageModalTexts = useMemo(() => {
    const fieldValue = formRef.getFieldValue('batchName')
    if(sageResMessage?.includes('successfully')) {
      return {
        title: 'Analysis started',
        subtitle: (<>Session sage has started her magic in the background. You&apos;ll receive an email once the analysis for <strong>&apos;{fieldValue}&apos;</strong> is complete.</>),
      }
    }
    if(sageResMessage?.includes('unsuccessful')) {
      return {
        title: 'Analysis failed',
        subtitle: (<>Session sage couldn&apos;t start the analysis for <strong>&apos;{fieldValue}&apos;</strong>. Please try again later.</>),
      }
    }
    return {
      title: 'Start session analysis',
      subtitle: 'Set up your session analysis by naming your batch. All sessions with a video on this page will be processed.',
    }
  }, [formRef, sageResMessage])
    // * CX-2105
    const sessionsNumFormatted = useMemo(() => {
        if (sessionStatisticsReducer?.statsBoxes) {
            return sessionsNum ? `${Intl.NumberFormat().format(sessionsNum) || 0} sessions` : 'No sessions'
        } 
        return 'Loading sessions ...'
    }, [sessionStatisticsReducer?.statsBoxes, sessionsNum]);
  
  const handleSageSubmit = useCallback( async () => {
    setSageLoading(true)

    const payload = {
      appid,
      batchname: formRef.getFieldValue('batchName'),
      emailid: formRef.getFieldValue('email'),
      sessionid: sessionIdList
    }

    await CommonApi.sageBatchNotify(payload)
    .then((res) => {
      setSageResMessage(res.data.message)
    })
    .catch(() => {
      setSageResMessage('unsuccesful')
    }).finally(() => {
      setSageLoading(false)
    })
  }, [appid, formRef, sessionIdList])

  const handleSageOpen = useCallback(() => {
    setOpenModal(true)
  }, [setOpenModal])

  const handleSageCancel = useCallback(() => {
    setOpenModal(false)
    setSageResMessage(null)
    formRef.setFieldsValue({ batchName: '', email: [] })
  }, [ formRef, setOpenModal ])

  const emailLabel = (email, index, removeEmail) => (
    <div data-tag key={index}>
      {email}
        {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
      <span data-tag-handle onClick={() => removeEmail(index)}>
        ×
      </span>
    </div>
  );


  return (
    <>
    {
      showSessionSage && (
      <CommonModal
        title={sageModalTexts.title}
        subtitle={sageModalTexts.subtitle}
        isModalOpen={openModal}
        handleOk={handleSageSubmit}
        handleCancel={handleSageCancel}
        hideButtons={!!sageResMessage}
        actionButtonTitles={{
          ok: 'Submit',
        }}
        loading={sageLoading}
        containerClassName='session-sage-modal'
        >
        {
          !sageResMessage ? (
            <FormContainer>
              <Form.Item label='Batch name' name='batchName' 
               rules={[
                { required: true, message: 'Please provide a batch name.' },
                {
                  max: 50,
                  message: 'The batch name is too long. Please make it shorter.',
                },
              ]}
              >
                <Input type='text' placeholder='Enter a name for this batch' />
              </Form.Item>
              <Form.Item
                name="email"
                label='Recipients'
                rules={[
                  {
                    required: true,
                    message: '',
                  },
                  {
                    validator: emailsValidateRule
                  }
                ]}
              >
                <Input.Group>
{                // eslint-disable-next-line jsx-a11y/no-static-element-interactions
}                <div
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault(); // To prevent the form from submitting when you press enter on the email field
                    }
                  }}
                  >
                  <ReactMultiEmail
                    style={{
                      fontSize: '12px',
                      overflowY: 'auto',
                      padding: '12px'
                    }}
                    placeholder="Enter recipients' email IDs"
                    onChange={(_emails) => {
                      formRef.setFieldsValue({ email: _emails });
                    }}
                    getLabel={emailLabel}
                    
                  />
                </div>
                </Input.Group>
              </Form.Item>
            </FormContainer>
          ) : <ButtonWrap><ButtonStyled type="primary" htmlType="button" onClick={handleSageCancel}>Ok</ButtonStyled></ButtonWrap>
        }
      </CommonModal>
      )
    }
      
    <ToolbarWrapper>
      { expanded && (
        <Bottom>
          <Quickbar
            applyQuickFilter={applyQuickFilter}
          />
        </Bottom>
      ) }
      <Top>
        <ToolbarLeft smaller={Boolean(sessionid)}>
          <SessionButton value={!expanded ? 'button' : 'text'} type="button" onMouseDown={!expanded ? handleSessionClick : null}>
            {!expanded ? <ArrowLeftIconSvg/> : ''} { !expanded ? 'Session list' : `${ sessionsNumFormatted }` }
          </SessionButton>
        </ToolbarLeft>
        <ToolbarRight>
          {expanded ? (
            <>
            {
              showSessionSage && ( 
                <SessionSageButton onClick={handleSageOpen} disabled={ sessionIdList.length === 0 || isFetching }>
                  <AiInputGradient /> Session sage
                </SessionSageButton>
              ) 
            } 
            <span data-intercom-target="List dropdown button">
                <Dropdown
                  overlayClassName={
                    sessionid
                      ? 'column-edit-dropdown session-detail-column-dropdown'
                      : 'column-edit-dropdown'
                  }
                  className="dropdown-btn"
                  trigger={['click']}
                  onVisibleChange={handleVisibleChange}
                  visible={dropdownVisible}
                  overlay={
                    <LoaderAdvanced
                      show={loading}
                      message={<LoaderInfo />}
                      backgroundStyle={{ backgroundColor: 'rgba(0, 0, 0, 0.0)' }}
                    >
                      <ColumnUpdate
                        type="session"
                        appid={appid}
                        dropdownVisible={dropdownVisible}
                        setLoading={setLoader}
                        setDropdownVisibility={setDropdownVisibility}
                        headers={headers}
                        showAddCustomUserButton
                        onResetSuccess={onResetSuccess}
                      />
                    </LoaderAdvanced>
              }
            >
              <Button>
                <ColumnIconSVG />
              </Button>
            </Dropdown>
            </span>
            <DownloadCSV/>
            </>
          ) : (
            <>
              <ShareSessionModal />
              <SessionOption />
              <Tooltip overlayClassName='custom-popover' placement='bottomRight' title='Close' align={{ offset: [8, 0] }}>
                <ButtonRound
                  onMouseDown={() => handleSessionClick('close')}
                >
                  <img src="/static/sessions/close.svg" alt="" />
                </ButtonRound>
              </Tooltip>
            </>
          )}
        </ToolbarRight>
      </Top>
    </ToolbarWrapper>
    </>
  )
}

export default memo(Toolbar);
