const TableViewBox = (props) => {
  const { sessionid, data, isFetching, handleSortBy, sortedBy, openIOSReplayModal } = props;
  const sortByTransform = (sort) => {
    if (sort.length > 0) {
      const { sortName, sortOrder, isCustomUserProperty } = sort[0];
      return [{
        id: sortName,
        desc: sortOrder === 'desc',
        ...isCustomUserProperty && { isCustomUserProperty },
      }]
    }
    return []
  }
  return (
    <TableBox>
      <SessionTable
        expanded={Boolean(sessionid)}
        data={data}
        isLoading={isFetching}
        setSortedBy={handleSortBy}
        sortedBy={sortedBy.length ? sortedBy : sortByTransform(data?.orderBy || [])}
        openIOSReplayModal={openIOSReplayModal}
      />
    </TableBox>
  )
}

const SessionDetailsAndVideo = () => {
  const [sortedBy, setSortedBy] = useState([]);
  const [isMounted, componentMountToggler] = useState(false);
  const [detailErrorMessage, setDetailErrorMessage] = useState();
  const {setOpenModal, CustomPropertyModal} = useCustomPropModal();
  const {localShowSchematicReplayModal, setSchematicReplayModal} = useSchematicReplay();
  
  const { monthsOfVideosAccessible } = useRestrictionContext();
  const dispatch = useDispatch();
  const document = window?.document || false;
  const {
    urlReducer: {
      sessionid,
      sessionpage = 1,
      appId,
      autoplay,
      parentType,
      notetab,
    },
    appFilter: {
      session: { segment: sessionSegment },
      sessionDetailSize,
      dateSegment,
      fetchProperty
    },
    currentOrgReducer: { planLimit },
  } = useSelector((state) => state);
  const multiScreenSkippedData = useScreenSkippedData();

  const userProperties = fetchProperty.user_custom_property.data || [];

  const {
    data: recordingData,
  } = useFetchAppSetting(['appSetting', appId], appId);

  const bottomRef = useRef(null);
  const sessionpageNumber = Number(sessionpage);
  const containerRef = useRef();

  let sessionsListReqBody = ''
  try {
    sessionsListReqBody = JSON.parse(
      localStorage.getItem('sessionsListReqBody')
    );
  } catch (err) {
    // silent fail
  }
  const queryClient = useQueryClient();

  const setSortByVal = (newSort) => {
    const {id, desc} = newSort()[0];
    const isCustomUserProperty = userProperties.includes(removeUxCamCustomProperty(id));
    const sortByVal = [{
      id,
      desc,
      ...isCustomUserProperty && { isCustomUserProperty }
    }]
    setSortedBy(sortByVal);
  }


  const cachedOrderBy = sessionsListReqBody?.appid === appId ? sessionsListReqBody?.orderBy : undefined;

  const postBody = useMemo(() => ({
    appid: appId,
    // filters: [ ...sessionSegment, ...[ { ...dateSegment } ] ],
    filters: sessionSegment,
    date_range: dateSegment,
    ...((sortedBy?.length || cachedOrderBy) && { orderBy: sortedBy?.length ? [{
      sortName: sortedBy[0]?.id,
      sortOrder: sortedBy[0]?.desc ? 'desc' : 'asc',
      ...sortedBy[0]?.isCustomUserProperty && { isCustomUserProperty: sortedBy[0]?.isCustomUserProperty }
    }] : cachedOrderBy }),
    page: sessionpageNumber || 1,
  }), [appId, dateSegment, sessionSegment, sessionpageNumber, cachedOrderBy, sortedBy]);

  const { sessionDetail } = useSessionTimeLine();
  const nativeIOSReplay = recordingData?.nativeScreenCapture || sessionDetail?.isNativeScreenCaptureEnabled || false;
  const { _id: currentSessionId, device } = sessionDetail || {};

  const showSchematicReplay = useMemo(() => !nativeIOSReplay && schematicFrameworks?.includes(device?.sdkPluginType?.toLowerCase()), [device?.sdkPluginType, nativeIOSReplay])

  const appIdJustChangedRef = useRef(false);
  useEffect(() => {
    appIdJustChangedRef.current = true;
    setSortedBy([]);
    try {
      localStorage.removeItem('sessionsListReqBody');
    } catch (err) {
      // silent fail
    }
  }, [appId]);

  useEffect(() => {
    if (appIdJustChangedRef.current) {
      appIdJustChangedRef.current = false;
      return;
    }
    try {
      localStorage.setItem('sessionsListReqBody', JSON.stringify(postBody));
    } catch (err) {
      // silent fail
    }
  }, [postBody]);
  const { data: dataBody, refetch, isFetching } = useSessionItems(postBody);
  const dataWithSessionLocked = useMemo(
    () => (
      {
        ...dataBody,
        data: {
          ...dataBody?.data,
          data: {
            ...dataBody?.data?.data,
            body: dataBody?.data?.data?.body?.map((item) => ({
              ...item,
              sessionLocked: monthsOfVideosAccessible && isDateOlderThanMonths( item.sessionUploadedDateTime, monthsOfVideosAccessible ) && planLimit?.videoRetentionTime !== planLimit?.videoPlaybackAccessibleTime
            }))
          }
        }
      }
    ),
    [dataBody, monthsOfVideosAccessible, planLimit]
  );
  const data = dataWithSessionLocked?.data?.data
  const handleSorting = (value) => {
    const sortedBody = {
      appid: appId,
      date_range: dateSegment,
      filters: sessionSegment,
      table: 'sessionTable',
      orderBy: value,
      page: 1,
    };
    getSessionSortedItems(sortedBody);
    // refetch ??
  };

  const callRedirectPage = () => {
    refetch();
    goToPage({
      page: 1,
      appId,
      sessionid,
      autoplay,
      segment: sessionSegment,
      parentType,
      expanded: !sessionid,
      notetab,
    });
  };

  const scrollToButtom = () => {
    setTimeout(() => {
      bottomRef?.current &&
        bottomRef.current.scrollIntoView({ block: 'end', behavior: 'smooth' });
    }, 500);
  };

  const session = useMemo(
    () =>
      data?.body
        ?.filter((el) => {
          if (el.sessionid === sessionid) {
            return el.userProperty;
          }
          return null;
        })
        .filter((el) => el)[0],
    [data, sessionid]
  );
  const saveDetailSize = (key, value) =>
    dispatch(setSessionDetailSizeByKey(key, value));

  const toggleFullScreen = useCallback(() => {
    if (document) {
      const container = containerRef.current;
      const isFullScreen = document.webkitCurrentFullScreenElement;
      const isFireFoxFullScreen = document.mozFullScreenElement;
      if (container) {
        if (isFullScreen) {
          document.webkitExitFullscreen && document.webkitExitFullscreen();
        } else {
          container.webkitRequestFullscreen &&
            container.webkitRequestFullscreen();
        }
        if (isFireFoxFullScreen) {
          document.mozCancelFullScreen && document.mozCancelFullScreen();
        } else {
          container.mozRequestFullScreen && container.mozRequestFullScreen();
        }
      }
    }
  }, [document]);

  const exitHandler = useCallback(() => scrollToButtom(), []);

  useEffect(() => {
    if (sortedBy?.length && sortedBy[0]?.sortName !== '') {
      callRedirectPage();
      const sortByVal = [{
        sortName: sortedBy[0]?.id,
        sortOrder: sortedBy[0]?.desc ? 'desc' : 'asc',
        ...sortedBy[0]?.isCustomUserProperty && { isCustomUserProperty: sortedBy[0]?.isCustomUserProperty }
      }]
      handleSorting(sortByVal);
    }
  }, [sortedBy]);

  useEffect(() => {
    if (data?.body?.length === 0 && sessionid) {
      goToPage({
        page: sessionpage,
        appId,
        segment: sessionSegment,
        parentType,
      });
    }
  }, [data]);

  useEffect(() => {
    if (sessionid && bottomRef?.current) scrollToButtom();
  }, [sessionid, bottomRef]);

  useEffect(() => {
    if (!isMounted) return;
    if (sessionid) {
      goToPage({
        page: 1,
        appId,
        segment: sessionSegment,
        parentType,
        dateSegment,
        sessionid,
        autoplay,
        notetab,
      });
      queryClient.invalidateQueries({ queryKey: ['sessionItems'] });
    } else callRedirectPage();
  }, [dateSegment.value, sessionSegment]);

  useEffect(() => {
    if (document) {
      componentMountToggler(true);
      document.addEventListener('fullscreenchange', exitHandler);
      document.addEventListener('webkitfullscreenchange', exitHandler);
    }

    return () => {
      componentMountToggler(false);
      document.removeEventListener('fullscreenchange', exitHandler);
      document.removeEventListener('webkitfullscreenchange', exitHandler);
    };
  }, [document, exitHandler]);

  const openIOSReplayModal = () => {
    if (!localShowSchematicReplayModal && showSchematicReplay) {
      setOpenModal(true);
      setSchematicReplayModal(true);
    }
  }

  return (
    <Wrapper expanded={Boolean(!sessionid)}>
      <CustomPropertyModal
        title={SchematicReplayModalConst.title}
        subtitle={SchematicReplayModalConst.subtitle}
        hideButtons
        containerClassName="schematic-replay-modal"
      >
        <SchematicIntercomText>
          To enable native screen recording, <Button type='link' onClick={() => showIntercom()}>please reach out to us.</Button>
        </SchematicIntercomText>
        <div className="modal-footer">
          <Button type="link">
            <a
              href={SchematicReplayModalConst.link}
              target="_blank"
              rel="noopener noreferrer"
            >
              Learn more
            </a>
          </Button>
          <Button type="primary" onClick={() => setOpenModal(false)}>
            Got it
          </Button>
        </div>
      </CustomPropertyModal>
    <Header>
      <OverviewBoxes />
    </Header>
    <Toolbar
      expanded={Boolean(!sessionid)}
      session={session}
      containerRef={containerRef}
      sessionList={data}
      isFetching={isFetching}
      onResetSuccess={() => setSortedBy([])}
    />
    <Main expanded={Boolean(sessionid)} ref={containerRef}>
      { parentType === 'sessionsList' && !sessionid && (
        <TableViewBox
          sessionid={sessionid || false}
          data={data}
          isFetching={isFetching}
          handleSortBy={setSortByVal}
          sortedBy={sortedBy}
          openIOSReplayModal={openIOSReplayModal}
        />
      ) }
      { sessionid && (
        <>
          <ResizePanel
            direction="e"
            handleClass="resize-handle"
            containerClass="resize-panel-container"
            borderClass="resize-border"
            initialWidth={
              parseInt(sessionDetailSize?.initial) > 518
                ? 518
                : parseInt(sessionDetailSize?.initial) < 250
                ? 250
                : sessionDetailSize?.initial
            }
            saveDetailSize={saveDetailSize}
          >
            <TableViewBox
              sessionid={sessionid || false}
              data={data}
              isFetching={isFetching}
              handleSortBy={setSortByVal}
              sortedBy={sortedBy}
              openIOSReplayModal={openIOSReplayModal}
            />
          </ResizePanel>
          <Box aria-label="video" className="middle-panel">
            <LoaderContainer aria-hidden={detailErrorMessage !== undefined || String(sessionid) === String(currentSessionId)}>
              <ReactLoader fullscreen />
            </LoaderContainer>
            <SessionDetails
              key={sessionid}
              sessionList={data}
              appId={appId}
              sessionId={sessionid}
              userId={session?.userProperty?.uxcamuserid}
              uploadedOn={session?.sessionUploadedDateTime}
              toggleFullScreen={toggleFullScreen}
              multiScreenSkippedData={multiScreenSkippedData}
              setDetailErrorMessage={setDetailErrorMessage}
            />
          </Box>
          <ResizePanel
            direction="w"
            handleClass="resize-handle"
            containerClass="resize-panel-container-second"
            borderClass="resize-border"
            initialWidth={
              parseInt(sessionDetailSize?.end) > 450
                ? 450
                : sessionDetailSize?.end
            }
            saveDetailSize={saveDetailSize}
          >
            <Box>
              <SessionDetailSideBar
                multiScreenSkippedData={multiScreenSkippedData}
                uploadedOn={session?.sessionUploadedDateTime}
                detailErrorMessage={detailErrorMessage}
              />
            </Box>
          </ResizePanel>
        </>
      ) }
    </Main>
    <div className="bottom" ref={bottomRef} />
  </Wrapper>
  );
};

export default memo(SessionDetailsAndVideo);
